-- ----------------------------
-- Table structure for project_budgets
-- ----------------------------
DROP TABLE IF EXISTS `project_budgets`;
CREATE TABLE `project_budgets` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '明细ID',
  `project_id` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '项目ID',
  `category` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '预算分类（拆除工程、水电安装、泥瓦工程、木工工程、油漆工程、材料费、人工费、管理费、其他）',
  `planned_amount` decimal(15,2) NOT NULL COMMENT '计划金额',
  `remarks` text COLLATE utf8mb4_unicode_ci COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `created_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `updated_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人',
  PRIMARY KEY (`id`),
  KEY `idx_project_id` (`project_id`),
  KEY `idx_category` (`category`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='预算明细表';

-- ----------------------------
-- Records of project_budgets
-- ----------------------------
BEGIN;
INSERT INTO `project_budgets` (`id`, `project_id`, `category`, `planned_amount`, `remarks`, `created_at`, `updated_at`, `created_by`, `updated_by`) VALUES ('963029b147ab429b9c59ba7637bab8e9', 'P2024110100001', '拆除工程', 222.00, '333', '2025-11-23 13:55:49', '2025-11-23 13:55:49', 'admin', NULL);
COMMIT;

-- ----------------------------
-- Table structure for project_members
-- ----------------------------
DROP TABLE IF EXISTS `project_members`;
CREATE TABLE `project_members` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '成员ID',
  `project_id` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '项目ID（逻辑关联）',
  `user_id` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '用户ID（逻辑关联）',
  `role` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '项目角色（DESIGNER:设计师、PM:项目经理、WORKER:工长、SUPERVISOR:监理）',
  `is_active` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否启用（0:已移除，1:在职）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `created_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人（添加成员的人）',
  `updated_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人（移除/修改的人）',
  PRIMARY KEY (`id`),
  KEY `idx_project_id` (`project_id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_role` (`role`),
  KEY `idx_is_active` (`is_active`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目成员表';

-- ----------------------------
-- Records of project_members
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for project_quality_fixes
-- ----------------------------
DROP TABLE IF EXISTS `project_quality_fixes`;
CREATE TABLE `project_quality_fixes` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '修复ID',
  `quality_issues_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '问题ID',
  `fix_description` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '修复描述',
  `images` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '修复图片JSON',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'IN_PROGRESS' COMMENT '修复状态(OPEN:未解决、IN_PROGRESS:解决中、RESOLVED:已解决)',
  `fixed_at` datetime DEFAULT NULL COMMENT '修复时间',
  `verified_at` datetime DEFAULT NULL COMMENT '验收时间',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `created_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `updated_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人',
  PRIMARY KEY (`id`),
  KEY `idx_quality_issues_id` (`quality_issues_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='问题修复表';

-- ----------------------------
-- Records of project_quality_fixes
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for project_rooms
-- ----------------------------
DROP TABLE IF EXISTS `project_rooms`;
CREATE TABLE `project_rooms` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '房间ID',
  `project_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '项目ID',
  `room_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '房间名称',
  `room_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '房间类型（客厅、卧室、厨房、卫生间、书房、餐厅、阳台、儿童房、老人房、衣帽间、储物间、其他）',
  `area` decimal(10,2) DEFAULT NULL COMMENT '房间面积（平米）',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT '房间描述',
  `floor` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '楼层信息',
  `orientation` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '朝向（N:北、S:南、E:东、W:西、NE:东北、NW:西北、SE:东南、SW:西南）',
  `file_ids` text COLLATE utf8mb4_unicode_ci COMMENT '关联文件ID数组（JSON格式：["f1", "f2", "f3"]）',
  `design_urls` text COLLATE utf8mb4_unicode_ci COMMENT '设计稿URL数组（JSON格式：["url1", "url2", "url3"]）',
  `construction_urls` text COLLATE utf8mb4_unicode_ci COMMENT '施工图URL数组（JSON格式）',
  `effect_urls` text COLLATE utf8mb4_unicode_ci COMMENT '效果图URL数组（JSON格式）',
  `other_urls` text COLLATE utf8mb4_unicode_ci COMMENT '其他文件URL数组（JSON格式）',
  `sort_order` int DEFAULT '0' COMMENT '排序（数字越小排序越靠前）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  `created_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `updated_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人',
  PRIMARY KEY (`id`),
  KEY `idx_project_id` (`project_id`),
  KEY `idx_room_type` (`room_type`),
  KEY `idx_active_deleted` (`deleted_at`),
  KEY `idx_sort_order` (`sort_order`),
  KEY `idx_room_name` (`room_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目房间表';

-- ----------------------------
-- Records of project_rooms
