-- ----------------------------
-- Table structure for project_schedule_records
-- ----------------------------
DROP TABLE IF EXISTS `project_schedule_records`;
CREATE TABLE `project_schedule_records` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '记录ID',
  `project_id` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '项目ID',
  `schedule_id` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '进度ID（逻辑关联）',
  `record_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '记录类型（START:开始、PROGRESS:进度更新、COMPLETE:完成、ISSUE:问题）',
  `completion_rate` decimal(5,2) DEFAULT NULL COMMENT '完成度百分比',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT '记录描述',
  `images` text COLLATE utf8mb4_unicode_ci COMMENT '现场图片JSON',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `created_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `updated_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人',
  PRIMARY KEY (`id`),
  KEY `idx_project_id` (`project_id`),
  KEY `idx_schedule_id` (`schedule_id`),
  KEY `idx_record_type` (`record_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='进度记录表';

-- ----------------------------
-- Records of project_schedule_records
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for project_schedules
-- ----------------------------
DROP TABLE IF EXISTS `project_schedules`;
CREATE TABLE `project_schedules` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '进度ID',
  `project_id` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '项目ID',
  `stage` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '施工阶段（DISMANTLING:拆除、WATER_ELECTRIC:水电、TILES:泥瓦、WOODWORK:木工、PAINTING:油漆、INSTALLATION:安装、SOFT_FURNISHING:软装、ACCEPTANCE:验收）',
  `stage_order` int NOT NULL COMMENT '阶段顺序（1-8）',
  `plan_start_date` datetime DEFAULT NULL COMMENT '计划开始日期',
  `plan_end_date` datetime DEFAULT NULL COMMENT '计划结束日期',
  `actual_start_date` datetime DEFAULT NULL COMMENT '实际开始日期',
  `actual_end_date` datetime DEFAULT NULL COMMENT '实际结束日期',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING' COMMENT '阶段状态',
  `completion_rate` decimal(5,2) DEFAULT '0.00' COMMENT '完成度百分比',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT '阶段描述',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `created_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `updated_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人',
  PRIMARY KEY (`id`),
  KEY `idx_project_id` (`project_id`),
  KEY `idx_stage` (`stage`),
  KEY `idx_status` (`status`),
  KEY `idx_stage_order` (`stage_order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目进度表';

-- ----------------------------
-- Records of project_schedules
-- ----------------------------
