-- ----------------------------
-- Table structure for projects
-- ----------------------------
DROP TABLE IF EXISTS `projects`;
CREATE TABLE `projects` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '项目ID',
  `project_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'RESIDENTIAL' COMMENT '项目类型（RESIDENTIAL:家装、COMMERCIAL:工装）',
  `name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '项目名称',
  `customer_id` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户ID',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT '项目描述',
  `address` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '项目地址',
  `area` decimal(10,2) DEFAULT NULL COMMENT '房屋面积（平米）',
  `budget` decimal(15,2) DEFAULT NULL COMMENT '预算金额',
  `actual_cost` decimal(15,2) DEFAULT '0.00' COMMENT '实际费用',
  `start_date` datetime DEFAULT NULL COMMENT '开始日期',
  `end_date` datetime DEFAULT NULL COMMENT '预计完工日期',
  `actual_end_date` datetime DEFAULT NULL COMMENT '实际完工日期',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PLANNING' COMMENT '项目状态',
  `priority` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MEDIUM' COMMENT '优先级',
  `progress` decimal(5,2) DEFAULT '0.00' COMMENT '进度百分比',
  `budgets_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预算文件URL',
  `contracts_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '合同文件URL',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  `created_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人',
  `updated_by` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人',
  PRIMARY KEY (`id`),
  KEY `idx_project_type` (`project_type`),
  KEY `idx_customer_id` (`customer_id`),
  KEY `idx_status` (`status`),
  KEY `idx_priority` (`priority`),
  KEY `idx_active_deleted` (`deleted_at`),
  KEY `idx_name` (`name`),
  KEY `idx_created_at` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='项目信息表';

